'use strict';
const $ = id => document.getElementById(id);
const D = window.YaparoResearch, E = window.YaparoDecision;
const state = {step:0,unlocked:0,brief:null,cards:[],selected:null,batch:0,history:[],plan:null,stale:true,revision:0,answers:{}};
const money = cents => new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(cents/100);
const percent = (n,t) => t ? (n/t*100).toLocaleString('tr-TR',{maximumFractionDigits:2}) : '0';
function el(tag,text,cls) {const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function btn(text,action,cls='text-button') {const b=el('button',text,cls);b.type='button';b.addEventListener('click',action);return b;}
function label(id) {return $(id).selectedOptions?.[0]?.textContent || $(id).value;}
function fillOptions(id,q,initial) {const s=$(id);s.replaceChildren();D.options.filter(o=>o.questionId===q).forEach(o=>{const n=el('option',o.label);n.value=o.value;s.append(n);});if(initial)s.value=initial;}
fillOptions('communication','S1_Q01','product_service_intro');fillOptions('business','S3_Q02','local_retail');
fillOptions('action','S1_Q04','visit_store');fillOptions('sector','S3_Q03','fashion_beauty_lifestyle');
fillOptions('goal','S3_Q01','store_visits');fillOptions('audience','S3_Q05','local_nearby');
const mq=D.questions.find(q=>q.field==='measurement_readiness');
if(mq)fillOptions('measurement',mq.id,'basic_utm');
else [['basic_utm','Temel UTM / platform sinyali'],['platform_pixel','Platform pikseli'],['pixel_capi_crm','Piksel + CRM'],['none','Henüz hazır değil']].forEach(([v,t])=>{const o=el('option',t);o.value=v;$('measurement').append(o);});
$('brief').value='Sentetik örnek: Kadıköy’deki tasarım butiğimde özgün parçaları tanıtmak ve yakındaki insanları mağazaya davet etmek istiyorum.';
$('audience-description').value='Yakındaki özgün tasarım meraklıları';
$('identity').value='Örnek Butik';
function go(step) {if(step>state.unlocked)return;state.step=step;document.body.classList.toggle('planning-stage',step===2);document.querySelectorAll('.step').forEach((n,i)=>n.hidden=i!==step);document.querySelectorAll('#step-nav button').forEach((n,i)=>{n.disabled=i>state.unlocked;n.classList.toggle('active',i===step);n.classList.toggle('done',i<step);if(i===step)n.setAttribute('aria-current','step');else n.removeAttribute('aria-current');});if(step===3)review();$('main').focus();window.scrollTo(0,0);}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>go(+b.dataset.step)));
// Incomplete branch-rule rows are not executable: use each question's showWhen instead.
function branches() {
  const root=$('branch-fields');root.replaceChildren();
  const base={...state.answers,S1_Q01:$('communication').value,S3_Q02:$('business').value};
  const qs=D.questions.filter(q=>q.stage===1 && Object.keys(q.showWhen).length && Object.entries(q.showWhen).every(([key,values])=>Array.isArray(base[key])?values.some(v=>base[key].includes(v)):values.includes(base[key])));
  if(!qs.length)return;
  const detail=el('details',undefined,'optional-details');detail.open=['fundraising','public_issue','sale_promotion'].includes(base.S1_Q01);detail.append(el('summary',`Bu isteğe özel ${qs.length} kısa ayrıntı`));
  const fields=el('div',undefined,'details-inner field-pair');
  qs.forEach(q=>{const box=el('div'),id=`q-${q.id}`;const l=el('label',q.label);l.htmlFor=id;box.append(l);
    const options=D.options.filter(o=>o.questionId===q.id);let input;
    if(options.length && q.type==='single_select'){input=el('select');const blank=el('option','Henüz bilmiyorum');blank.value='';input.append(blank);options.forEach(o=>{const n=el('option',o.label);n.value=o.value;input.append(n);});}
    else {input=el(q.type==='textarea'?'textarea':'input');if(q.type==='number'){input.type='number';input.min='0';}else if(input.tagName==='INPUT')input.type='text';input.maxLength=q.validation.max_chars||600;input.placeholder=['single_select','textarea','number'].includes(q.type)?'Kısa bilgi ekle':'Taslak notu · belge / onay doğrulanmaz';}
    input.id=id;input.value=state.answers[q.id]||'';input.dataset.question=q.id;input.addEventListener('input',()=>{state.answers[q.id]=input.value;invalidate();});box.append(input,el('p',q.help,'hint'));fields.append(box);
  });detail.append(fields,el('p','Bu ayrıntılar içerik notudur. Bilinmeyen cevaplar doğrulanmış sayılmaz; belgeler yüklenmez ve politika kapıları açılmaz.','hint details-hint'));root.append(detail);
}
branches();$('communication').addEventListener('change',branches);$('business').addEventListener('change',branches);
function invalidate(){state.stale=true;state.unlocked=Math.min(state.unlocked,2);if(state.plan)$('decision-status').textContent='Koşullar değişti. Önce dağılımı yeniden öner; önceki sonuç güncel değil.';}
$('brief-form').addEventListener('input',invalidate);$('brief-form').addEventListener('change',invalidate);
function briefObject(){const visible={};document.querySelectorAll('[data-question]').forEach(n=>visible[n.dataset.question]=n.value);return {communication:$('communication').value,business:$('business').value,action:$('action').value,description:$('brief').value.trim(),audience:$('audience-description').value.trim(),sector:$('sector').value,risk:$('risk').value,identity:$('identity').value.trim(),message:$('message').value.trim(),branch:visible};}
function makeCards(){if(state.cards.length)state.history.push({cards:state.cards,selected:state.selected});state.batch++;const b=state.brief;
  const routes=[['Ürünün hikâyesi','değer','Tek bir farkı görünür kıl.','Ayrıntıları keşfet','Sade ve güven veren'],['Bir anın hissi','duygu','Kendine ait bir an yarat.','Sana yakın olanı bul','Sıcak ve samimi'],['Merak uyandıran davet','merak','Alıştığından farklı bir şey.','Yakından tanı','Cesur ve enerjik']];
  state.cards=routes.map((r,i)=>({id:`route-${state.batch}-${i}`,angle:r[0],hook:r[1],title:state.batch%2?r[2]:['Hikâyene yeni bir detay.','Gününe küçük bir güzellik.','Yeni bir bakışa hazır mısın?'][i],message:b.message||['Özgün bir seçimin arkasındaki emeği keşfet.','Sana iyi gelen bir tarzla tanış.','Yeni bir deneyime yer aç.'][i],cta:r[3],tone:r[4],format:'static_image',proof:'Kanıt doğrulanmadı',claims:[],channelAffinity:i===0?'Arama + görsel keşif':'Görsel keşif',x:10,y:15,revision:1,kind:i,edits:[]}));
  state.selected=null;state.unlocked=1;invalidate();renderCards();}
$('brief-form').addEventListener('submit',e=>{e.preventDefault();if($('brief').value.trim().length<10){$('brief').setCustomValidity('En az 10 karakterle neyi tanıttığını anlat.');$('brief').reportValidity();return;}
  const b=briefObject(),changed=JSON.stringify(b)!==JSON.stringify(state.brief);state.brief=b;if(changed||!state.cards.length)makeCards();state.unlocked=Math.max(state.unlocked,1);go(1);
});$('brief').addEventListener('input',()=>$('brief').setCustomValidity(''));
function artwork(card){const art=el('div',undefined,`art art-${['a','b','c'][card.kind]}`);art.append(el('div',undefined,'art-orbit'),el('div',undefined,'art-product'));const t=el('div',card.title,'art-title');t.style.left=`${card.x}%`;t.style.top=`${card.y}%`;art.append(t,el('span',state.brief?.identity||'YAPARO · ÖRNEK ÇİZİM','art-brand'));return art;}
function renderCards(){const root=$('concepts');root.replaceChildren();state.cards.forEach(c=>{const article=el('article',undefined,`concept-card ${state.selected===c.id?'selected':''}`);article.append(artwork(c));const info=el('div',undefined,'concept-info');info.append(el('h2',c.angle),el('p',c.message),el('div',`${c.tone} · Statik görsel`,'concept-meta'),el('small',`Kanca: ${c.hook} · CTA: ${c.cta}`));
    const actions=el('div',undefined,'card-actions'),choose=btn(state.selected===c.id?'✓ Seçildi':'Bu yönü seç',()=>{state.selected=c.id;invalidate();state.unlocked=2;renderCards();},'choose');choose.setAttribute('aria-pressed',String(state.selected===c.id));
    actions.append(choose,btn('Düzenle',()=>openEditor(c)),btn('Benzerini gör',()=>{c.edits.push({title:c.title,message:c.message,cta:c.cta,x:c.x,y:c.y});c.title=c.revision%2?'Küçük detaylar, büyük bir his.':'Yeni bir bakışa yer aç.';c.revision++;invalidate();renderCards();}));
    if(c.edits.length)actions.append(btn('Geri al',()=>{Object.assign(c,c.edits.pop());c.revision++;invalidate();renderCards();}));info.append(actions);article.append(info);root.append(article);});$('content-next').disabled=!state.selected;
  let back=$('previous-trio');if(!back){back=btn('Önceki üçlü',()=>{const old=state.history.pop();if(old){state.cards=old.cards;state.selected=old.selected;invalidate();renderCards();}});back.id='previous-trio';$('regenerate').after(back);}back.hidden=!state.history.length;
}
$('regenerate').addEventListener('click',makeCards);
let editing=null,edited=null;
function openEditor(c){editing=c;edited={...c};for(const [field,key] of [['edit-title','title'],['edit-message','message'],['edit-cta','cta'],['edit-x','x'],['edit-y','y']])$(field).value=c[key];$('editor-preview').replaceChildren(artwork(c));$('editor').showModal();}
for(const [field,key] of [['edit-title','title'],['edit-message','message'],['edit-cta','cta'],['edit-x','x'],['edit-y','y']])$(field).addEventListener('input',()=>{edited[key]=['x','y'].includes(key)?+$(field).value:$(field).value;$('editor-preview').replaceChildren(artwork(edited));});
$('editor-cancel').addEventListener('click',()=>$('editor').close());$('editor-save').addEventListener('click',()=>{if(!edited.title.trim()||!edited.cta.trim())return;editing.edits.push({title:editing.title,message:editing.message,cta:editing.cta,x:editing.x,y:editing.y});Object.assign(editing,edited);editing.revision++;invalidate();renderCards();$('editor').close();});
function inputs(){return {budget:+$('budget').value,days:+$('duration').value,value:+$('order-value').value,margin:+$('margin').value,cpa:+$('cpa').value,capacity:+$('capacity').value,goal:$('goal').value,business:$('business').value,audience:$('audience').value,sector:$('sector').value,risk:$('risk').value,communication:$('communication').value,action:$('action').value,geo:{area:'district_city',radius:'radius_local',country:'nationwide'}[$('geo-mode').value],radius:+$('radius').value,region:$('region').value,start:$('start').value,measurement:$('measurement').value,fixture:$('fixture').value,video:$('video').checked,catalog:$('catalog').checked,tracking:$('tracking').checked};}
function recommend(){if(!$('plan-form').reportValidity())return;try{state.plan=E.evaluate(inputs(),D);state.revision++;state.stale=false;renderPlan();$('decision-status').textContent=`Öneri ${state.revision} · Mevcut koşullar yeniden değerlendirildi. ${state.plan.bound?'27 Ekim 2026 tarihli TEMSİLİ SC01 verisi kullanıldı.':'Bu koşullara bağlı tahmin yok; bütçe önerilmedi.'} Canlı sorgu yapılmadı.`;}catch(err){state.stale=true;$('decision-status').textContent=err.message;}}
$('recommend').addEventListener('click',recommend);$('content-next').addEventListener('click',()=>{if(!state.selected)return;state.unlocked=2;$('intent-summary').textContent=`${label('business')} · ${label('action')} · ${state.brief.audience}`;go(2);if(!state.plan||state.stale)recommend();});
$('plan-form').addEventListener('input',e=>{if(!e.target.closest('#recommended'))invalidate();});$('plan-form').addEventListener('change',e=>{if(!e.target.closest('#recommended'))invalidate();});
function geoVisibility(){$('radius-field').hidden=$('geo-mode').value!=='radius';$('radius').disabled=$('radius-field').hidden;$('region').required=$('geo-mode').value!=='country';}
$('geo-mode').addEventListener('change',geoVisibility);geoVisibility();
function guide(row){$('guide-title').textContent=row.channel.name;const root=$('guide-body');root.replaceChildren();const pairs=[['Durum',row.amount?'Önerildi':row.owned?'Bütçe dışı aksiyon':row.eligible?'Koşullu / portföy dışında':'Bu koşullarda seçilmedi'],['Neden',row.reasons.map(x=>E.reasonText[x]).join(' · ')||'Anlamlı test ve tavan koşulları karşılandı.'],['Teknik minimum',row.platform===null?'Hesap / para birimi doğrulaması bekliyor':money(row.platform)],['Anlamlı test minimumu',money(row.useful)],['Faydalı tavan',row.cap===null?'Tahmin yok, hesaplanmadı':money(row.cap)],['Tavanın kaynağı','Temsili talep, toplam bütçe ve ortak işletme kapasitesi / marj sınırının en küçüğü'],['Uzman uygunluğu',`${row.score}/100 · başarı olasılığı değildir`],['Tahmin kaynağı / tarihi',`${row.f?.quality||'Yok'} · ${row.f?.updated||'Yok'} · yalnız SC01`],['Bu koşula bağlı mı?',state.plan.bound?'Evet, tarihli sentetik fixture':'Hayır: gerçek tahmin yenilemesi gerekli'],['Satın alma biçimi',row.channel.purchase],['Nerede işe yarar?',row.channel.best],['Hazırlık',row.channel.assets.join(' · ')],['Coğrafya araştırma notu',row.channel.geo],['Sınır',row.channel.note]];
  const dl=el('dl',undefined,'guide-dl');pairs.forEach(([k,v])=>dl.append(el('dt',k),el('dd',v)));root.append(dl);const det=el('details');det.append(el('summary','Puanın 8 boyutunu incele'));row.breakdown.forEach(x=>det.append(el('p',`${x.dimension}: ${x.score}/5 × %${x.weight} = ${x.points} puan`)));root.append(det);
  row.channel.sourceIds.forEach(id=>{const s=D.sources.find(s=>s.id===id);if(!s)return;const p=el('p',`${id} · ${s.title} · ${s.publisher} · araştırma kaynağı; bağımsız kontrol edilmedi`,'hint');if(/^https:\/\//.test(s.url)){const a=el('a','Kaynağı aç');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';p.append(' ',a);}root.append(p);});$('guide').showModal();}
$('guide-close').addEventListener('click',()=>$('guide').close());
function renderPlan(){const p=state.plan;if(!p)return;const stats=$('plan-summary');stats.replaceChildren();[['Toplam bütçe',money(p.total)],['Önerilen yatırım',money(p.allocated)],['Ayrılmamış bütçe',money(p.unallocated)]].forEach(([t,v])=>{const n=el('div',undefined,'summary-stat');n.append(el('span',t),el('strong',v));stats.append(n);});
  const upper=$('recommended'),lower=$('other-channels');upper.replaceChildren();lower.replaceChildren();
  const groups={};[['paid','Diğer reklam ürünleri'],['managed','Partner / yönetilen satın alma'],['owned','Reklam bütçesi dışındaki aksiyonlar']].forEach(([id,title])=>{const g=el('section',undefined,'catalog-group');g.append(el('h3',title));lower.append(g);groups[id]=g;});
  const ordered=[...p.rows].sort((a,b)=>b.amount-a.amount || b.score-a.score);
  ordered.forEach(r=>{const row=el('article',undefined,r.amount?'channel-row':'other-channel');row.dataset.channel=r.channel.id;const main=el('div',undefined,'channel-main');main.append(el('span',r.channel.family.slice(0,2),'channel-logo'));const info=el('div',undefined,'channel-info');info.append(el('h3',r.channel.name),el('p',r.amount?`${r.score}/100 uygunluk · ${money(r.useful)} test min. · ${money(r.cap)} tavan`:r.reasons.map(x=>E.reasonText[x]).join(' · ')||'Uygun aday; şu an pay ayrılmadı'));main.append(info);row.append(main);
    const controls=el('div',undefined,'channel-allocation');if(r.amount){const input=el('input');input.type='number';input.min='0';input.max=(r.cap/100).toFixed(2);input.step='0.01';input.value=(r.amount/100).toFixed(2);input.setAttribute('aria-label',`${r.channel.name} bütçesi TL`);input.addEventListener('change',()=>{try{E.manual(p,r.channel.id,Math.round(Number(input.value)*100));renderPlan();$('decision-status').textContent='Manuel tutar uygulandı. Yeniden öner düğmesi bu değişikliği sıfırlar.';}catch(err){$('decision-status').textContent=err.message;input.value=(r.amount/100).toFixed(2);}});controls.append(input,el('span',`TL · %${percent(r.amount,p.total)}`));}
    else if(r.eligible){controls.append(btn('Plana ekle',()=>{try{E.manual(p,r.channel.id,r.useful);renderPlan();}catch(err){$('decision-status').textContent=err.message;}},'secondary'));}
    else controls.append(el('span',r.owned?'Bütçe dışı':r.reasons.includes('policy_review')?'İnceleme':'Eksik koşul','status'));
    const book=btn('ⓘ',()=>guide(r),'book-button');book.setAttribute('aria-label',`${r.channel.name} neden ve koşullar`);controls.append(book);row.append(controls);
    if(r.amount){
      const slider=el('input');slider.type='range';slider.min='0';slider.max=String(r.cap);slider.step='1';slider.value=String(r.amount);slider.className='share-slider';slider.setAttribute('aria-label',`${r.channel.name} payını ayarla`);
      slider.addEventListener('change',()=>{try{E.manual(p,r.channel.id,+slider.value);renderPlan();$('decision-status').textContent='Payı değiştirdin. Minimum ve tavan korundu; kalan tutar ayrılmamış bütçede.';}catch(err){$('decision-status').textContent=err.message;slider.value=String(r.amount);}});
      row.append(slider);upper.append(row);
    }else groups[r.owned?'owned':/managed|partner|creator/.test(r.channel.purchase)?'managed':'paid'].append(row);
  });if(!p.allocated)upper.append(el('p',p.blocked?'Bu istekte önce belge / politika incelemesi gerekli. İçerik taslağın korunuyor.':'Bu koşullarda uygulanabilir bir bütçe önerisi yok. Eksik koşulları aşağıdan inceleyebilirsin.','empty-state'));
  $('why-plan').replaceChildren(el('strong','Bu plan neden böyle?'),el('p',p.blocked?'İnceleme kapısı kanal puanından önce gelir; kullanıcı beyanı belge onayı sayılmaz.':p.bound?'Kanallara önce anlamlı test tutarı ayrıldı. Kalan tutar uzman puanının karesiyle, talep ve ortak işletme tavanlarına kadar dağıtıldı. Kalan bütçeyi harcamak zorunda değilsin.':'Örnek Kadıköy tahmini başka bölgeye, hedefe, tarihe veya kitleye taşınmadı. Gerçek hesaptan yeni bir tahmin alınmadan kesin rakam gösterilmez.'),el('small',`${D.version} · 8 boyutlu uzman başlangıç puanları · bağımsız hukuki / platform doğrulaması yok · AI çağrısı yok`));
}
$('plan-form').addEventListener('submit',e=>{e.preventDefault();if(!state.plan||state.stale){$('decision-status').textContent='Koşullar değişti. Önce dağılımı yeniden öner.';return;}state.unlocked=3;go(3);});
function review(){const p=state.plan,c=state.cards.find(c=>c.id===state.selected),root=$('review');root.replaceChildren();if(!p||!c)return;const visual=el('div');visual.append(artwork(c));const body=el('section',undefined,'review-panel'),dl=el('dl');const pairs=[['İletişim işi',label('communication')],['İstek',state.brief.description],['Kitle',state.brief.audience],['İstenen aksiyon',label('action')],['Yaratıcı rota',`${c.angle} · ${c.tone} · ${c.format} · revizyon ${c.revision}`],['Mesaj / CTA',`${c.title} · ${c.message} · ${c.cta}`],['Reklam hedefi',label('goal')],['Bölge',`${p.input.geo==='nationwide'?'Türkiye':p.input.region}${p.input.geo==='radius_local'?` · ${p.input.radius} km`:''} · hedefleme doğrulanmadı`],['Önerilen bütçe',money(p.allocated)],['Ayrılmamış bütçe',money(p.unallocated)],['Kanal planı',p.rows.filter(r=>r.amount).map(r=>`${r.channel.name}: ${money(r.amount)}`).join(' · ')||'Koşullar bekliyor'],['Veri durumu','Tarihli SC01 temsili verisi · gerçek sonuç / getiri garantisi yok'],['Üretim ve hizmet bedeli','Bu prototipte hesaplanmaz; medya bütçesinden ayrıdır'],['Yayın hazırlığı','KAPALI · gerçek hesap, izin, ölçüm ve platform tahminleri bekliyor']];pairs.forEach(([k,v])=>dl.append(el('dt',k),el('dd',v)));body.append(dl);root.append(visual,body);$('finish-status').textContent='';$('finish').disabled=false;}
$('finish').addEventListener('click',()=>{$('finish-status').textContent='Taslak kontrol edildi. Kalıcı kayıt, AI çağrısı, ödeme ve reklam yayını yapılmadı.';$('finish').disabled=true;});
function chat(t){const log=$('chat-log');log.append(el('div',t,'user-message'));const lower=t.toLocaleLowerCase('tr-TR');let answer='Bu yardımcı yerel ve sabit kurallıdır. Seçimlerini değiştirmek için formdaki alanları kullan; mesajın otomatik uygulanmaz.';
  if(/neden|kanal|bütçe|dağı/.test(lower))answer=state.plan?`Şu an ${money(state.plan.allocated)} önerildi, ${money(state.plan.unallocated)} ayrılmadı. Önce uygunluk kapıları, sonra anlamlı minimum ve tavanlar uygulanır. Kanalın ⓘ düğmesinde nedenlerini görebilirsin.`:'İlk önce isteğini ve yaratıcı yönünü seç. Kanal ve bütçe planı o bilgilerle birlikte değerlendirilir.';
  if(/izin|yardım|sağlık/.test(lower))answer='Belge / politika incelemesi gerekirse taslağın korunur, ücretli öneri ve yayın kapalı kalır. Bu ekran belge kabul etmez ve doğrulama yapmaz.';
  log.append(el('div',answer,'assistant-message'));while(log.children.length>24)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;
}
$('chat-form').addEventListener('submit',e=>{e.preventDefault();const t=$('chat-input').value.trim();if(t)chat(t);$('chat-input').value='';});
$('helper-toggle').addEventListener('click',()=>{const open=$('helper-panel').classList.toggle('mobile-open');$('helper-toggle').setAttribute('aria-expanded',String(open));if(open)$('chat-input').focus();});
window.YaparoStudio = {getSnapshot:()=>structuredClone({brief:state.brief,creative:state.cards.find(c=>c.id===state.selected),plan:state.plan,stale:state.stale,revision:state.revision})};
// Keep campaign conditions and their consequences side by side, not in a long column.
const planForm=$('plan-form'), planControls=el('div'), planResults=el('div');planControls.id='plan-controls';planResults.id='plan-results';
let resultSection=false;[...planForm.children].forEach(node=>{if(node.classList.contains('form-footer'))return;if(node.classList.contains('decision-toolbar'))resultSection=true;(resultSection?planResults:planControls).append(node);});planForm.prepend(planControls,planResults);
['order-value','margin','cpa','capacity'].forEach(id=>$(id).required=true);
